# Dense architecture, three unequal columns and coloured header strips.
def card(t,c,body):return f'<section style="--c:{c}"><h2>{t}</h2><div class="inside">{body}</div></section>'
def boxes(items):return '<div class="chain">'+''.join('<span>'+x+'</span>' for x in items)+'</div>'
a=card('Skills — Task Knowledge','#0085ff','<b>Load the procedure when it is needed</b>'+boxes(['User request → Identify skill','Read instructions → Execute','Inspect output → Verify'])+'<ul><li>Reusable procedures and examples</li><li>Supporting scripts and resources</li><li>Relevant context loaded on demand</li><li>Version and test on real tasks</li></ul>')+card('The Core Agent Loop','#ff6500',boxes(['Understand the goal','↓','Plan → Act → Observe','↑ &nbsp; Revise &nbsp; ↵'])+'<div class="brain">AGENT<br>Model + tools<br>State + context</div><p>Stop when the goal is met, the budget is reached, or human judgment is needed.</p>')
