c=card('Files & Knowledge Sources','#934eff',boxes(['Project instructions','Guides / Reference material','Search / Retrieval'])+'<p>Keep evidence relevant, current and traceable to its source.</p>')+card('Subagents — Delegated Work','#ff6500',boxes(['Research → Evidence','Build → Artifact','Review → Findings'])+'<p>Clear scope. Necessary context.<br>Check every handoff.</p>')+card('Plugins — Capability Packages','#0085ff',boxes(['Skills + Tools + Integrations','↓','Host-specific package'])+'<p>Review dependencies and access.</p>')
